<?php
/**
 * 日本地図(地方別)
 *  ・地図の形は、47都道府県のタイル型SVG
 *  ・学割NAVIの「地域」(region-type)は都道府県ではなく地方単位なので、都道府県を地方ごとにまとめ、
 *    どの都道府県も、その地方の一覧ページへのリンクにしている(「全国」は、地図には載せない)
 *  ・地図の上や、右の一覧に、マウスを重ねると、同じ地方が同時に色づく(script.js)
 */
$gw_map_regions = array(
    'hokkaido'        => '北海道',
    'tohoku'          => '東北',
    'kanto'           => '関東',
    'chubu'           => '中部',
    'kinki'           => '近畿',
    'chugoku-shikoku' => '中国・四国',
    'kyushu-okinawa'  => '九州・沖縄',
);
$gw_map = array();
foreach ($gw_map_regions as $slug => $label) {
    $term = get_term_by('slug', $slug, 'region-type');
    $link = $term ? get_term_link($term) : '';
    $gw_map[$slug] = array(
        'label' => $label,
        'count' => $term ? (int) $term->count : 0,
        'link'  => (is_wp_error($link) || !$link) ? '#' : $link,
    );
}
$gw_all = get_term_by('slug', 'all-over', 'region-type');
$gw_all_link = $gw_all ? get_term_link($gw_all) : '';
?>
